contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: attempt withdraw/withdrawAll from this contract (not owner)
    // params choose which function and value to attempt to withdraw
    function run(bool callWithdrawAll, uint amount) public payable {
        // ensure this contract has enough balance to try sending Ether to c if needed
        // but we do not send Ether to c here: we only call withdraw/withdrawAll which should revert when not owner
        // record balance before
        uint balBefore = address(c).balance;

        bool reverted;
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balAfter = address(c).balance;

        // General invariant: if caller is not the owner (this contract wasn't the deployer of c), withdraw/withdrawAll must revert and c's balance must be unchanged.
        // We cannot directly know owner from here, but when InvMutTest is not the owner then calls must revert. Since the checker deploys a fresh C with msg.sender == InvMutTest's deployer (the test runner),
        // in that environment this contract is NOT the owner. So we assert: if the call did not revert then balance may decrease, otherwise balance stays the same.
        // Expressed as: reverted OR balAfter == balBefore
        assert(reverted || balAfter == balBefore);
    }

    // allow receiving Ether if withdrawn to this contract in some scenarios (though owner-only should prevent that here)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test: when this contract (not owner) calls withdraw or withdrawAll, if the call succeeds then
    // the decrease in c's balance equals the increase in this contract's balance; if it reverts then balances unchanged.
    function run(bool callWithdrawAll, uint amount) public payable {
        // record balances before
        uint balC_before = address(c).balance;
        uint balT_before = address(this).balance;

        bool reverted;
        // Make the call as a top-level statement. Use try/catch to capture revert without nesting the call inside other expressions.
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint balC_after = address(c).balance;
        uint balT_after = address(this).balance;

        // General rule: either the call reverted and both balances unchanged, or it succeeded and
        // the decrease in c equals the increase in this contract.
        assert(
            (reverted && balC_after == balC_before && balT_after == balT_before)
            || (!reverted && (balC_before - balC_after) == (balT_after - balT_before))
        );
    }

    receive() external payable {}
}

