contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public property test function
    // params: caller address (simulated by using low-level call from this contract via callOnBehalf flag),
    // amount to deposit to C via its receive, and amount to attempt to withdraw
    function run(address caller, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Initially record observable state
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Make this contract send Ether to c to trigger receive() which increases depositsCount
        // Use a direct call to send Ether from this contract
        if (depositAmount > 0) {
            // ensure the transfer triggers receive
            (bool ok, ) = address(c).call{value: depositAmount}("");
            // If receive reverts due to any reason (shouldn't for non-overflow), consider that as deposit failed
            if (!ok) {
                // deposit failed: depositsCount and balance should be unchanged
                assert(c.depositsCount() == beforeDeposits);
                assert(address(c).balance == beforeBalance);
                return;
            }
        }

        // After deposit attempt, record state
        uint midDeposits = c.depositsCount();
        uint midBalance = address(c).balance;

        // Now attempt to call withdraw as 'caller'. Because the checker runs in a single tx and msg.sender
        // for calls to c will be this contract, we simulate caller by having c.sendMoney attempt to call
        // withdraw indirectly is not possible. Instead we test ownership by directly calling withdraw from
        // this contract and treating 'caller' parameter to decide whether this contract is the owner.
        // The constructed c was deployed with msg.sender being the account that deployed it (the test harness),
        // but per problem description, c is freshly deployed and msg.sender for that deployment was the test harness
        // (not this contract). Therefore this contract is NOT the owner. So attempts to call withdraw should revert.

        // Attempt withdraw and capture revert
        bool revertedWithdraw;
        try c.withdraw(withdrawAmount) {
            revertedWithdraw = false;
        } catch {
            revertedWithdraw = true;
        }

        bool revertedWithdrawAll;
        try c.withdrawAll() {
            revertedWithdrawAll = false;
        } catch {
            revertedWithdrawAll = true;
        }

        // Final observed state
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule asserted:
        // If this contract is not the owner (which is true because owner was set at c construction to msg.sender of deployer),
        // then both withdraw and withdrawAll must revert and must not change c's balance or depositsCount.
        // We express "not owner" by checking that calling withdraw reverted (if it didn't revert, it indicates owner rights).
        // The assert ensures that whenever withdraw reverted, the state stayed same and withdrawAll also reverted.
        assert(
            // If withdraw reverted then neither balance nor depositsCount changed and withdrawAll also reverted
            (revertedWithdraw == true && afterDeposits == midDeposits && afterBalance == midBalance && revertedWithdrawAll == true)
            // OR if withdraw did not revert then it's an ownership action: in that case we require consistency that afterBalance <= midBalance
            // and depositsCount can only have increased by the receive call (no decrease). This branch keeps the rule general.
            || (revertedWithdraw == false && afterDeposits >= midDeposits && afterBalance <= midBalance)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public property test function
    // Params: amount to send to c to trigger receive()
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance for deposit");

        // Observe state before
        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = address(c).balance;

        // Attempt to send Ether to c to trigger receive(); capture whether it reverted
        bool reverted;
        try c /* no-op to satisfy syntax for try with external call */.withdraw(0) {
            // This try is only to allow the following try/catch to compile in older solc patterns;
            // It will not be executed because we immediately perform the actual call below.
        } catch {}

        // Perform the state-changing low-level call to trigger receive via the public surface: a direct payable call
        // Must be a top-level statement and not nested. Use address(c).call{value: depositAmount}("") which is allowed
        // because it invokes c's receive; capture revert by testing the returned bool
        (bool ok, ) = address(c).call{value: depositAmount}("");
        reverted = !ok;

        // Observe state after
        uint afterDeposits = c.depositsCount();
        uint afterBalance = address(c).balance;

        // General rule: if the deposit call did not revert, depositsCount increases by exactly 1
        // and the contract balance increases by exactly depositAmount. If it reverted, both remain unchanged.
        assert(
            (reverted && afterDeposits == beforeDeposits && afterBalance == beforeBalance)
            || (!reverted && afterDeposits == beforeDeposits + 1 && afterBalance == beforeBalance + depositAmount)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public property test
    // params: caller (simulated by using try/catch on c.withdraw), amount to attempt to withdraw
    function run(uint withdrawAmount) public payable {
        // Ensure this test contract has enough balance to fund C so that withdraw could succeed if owner
        require(address(this).balance >= withdrawAmount, "insufficient balance for funding C");

        // Fund C so there is balance to withdraw
        c.sendMoney(address(c), 0); // harmless call to satisfy top-level state-change requirement pattern (no effect)
        // Actually transfer Ether to C by using a direct payable call to address(c)
        (bool fundOk, ) = address(c).call{value: withdrawAmount}("");
        // after funding, record balance
        uint beforeBalance = address(c).balance;

        // Now attempt to call withdraw as this contract (which is NOT the original owner of C)
        bool reverted;
        try c.withdraw(withdrawAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;

        // General rule: if a non-owner calls withdraw, it must revert and the contract balance stays the same.
        // Since InvMutTest is not the deployer/owner of C, the call should revert; if it didn't, balance would decrease.
        assert(reverted && afterBalance == beforeBalance);
    }

    receive() external payable {}
}

