contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take as inputs: callerIsOwner flag (whether this contract should act as owner),
    // an amount to deposit into c, and an amount to attempt to withdraw.
    // To deposit we send Ether from this contract to c by calling its receive via a plain transfer (call with empty data).
    function run(bool callerIsOwner, uint depositAmount, uint withdrawAmount) public payable {
        require(true);

        // Ensure this test contract has enough balance to send depositAmount
        require(address(this).balance >= depositAmount);

        // If we want this contract to be owner, it must be the deployer of C.
        // The testing harness deploys a fresh C whose owner == msg.sender at construction time.
        // In that deployment the deployer is the external account that created C, not this test contract.
        // So callerIsOwner == true is only possible if the checker arranged for that; we do not enforce it here.

        // Record balances before
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        uint beforeDepositsCount = c.depositsCount();

        // Make a deposit to C by calling receive(): use call with empty data and value
        (bool sent,) = address(c).call{value: depositAmount}("");
        // sent indicates whether receive() accepted and didn't revert

        // Read state after deposit attempt
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        uint afterDepositsCount = c.depositsCount();

        // Now attempt to withdraw withdrawAmount via withdraw(). withdraw may only succeed if msg.sender == owner.
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Also attempt withdrawAll in a separate try to observe its behavior
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // After withdraw attempts, capture balances
        uint finalCBalance = address(c).balance;
        uint finalThisBalance = address(this).balance;

        // General invariant we assert:
        // If withdraw (or withdrawAll) reverted, then the contract's Ether balance did not decrease because of that call;
        // conversely, if withdraw succeeded, then the caller must have been the owner (msg.sender == owner), which for this test means
        // the C contract's owner equals address(this) and the C's balance decreased by the withdrawn amount (bounded by prior balance).
        // We cannot directly read owner, but we can observe that if a withdraw succeeded then address(this) received additional Ether (or balance shift) and finalCBalance <= afterCBalance.
        // The single assert captures that: either withdraw reverted and balance stayed same as before withdraws, or withdraw succeeded and C's balance decreased.

        assert(
            (
                (withdrawReverted && withdrawAllReverted && finalCBalance == afterCBalance)
            ) || (
                ((!withdrawReverted || !withdrawAllReverted) && finalCBalance <= afterCBalance)
            )
        );
    }

    // Allow receiving Ether so withdraw can send to this contract
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs:
    // callDeposit: amount of Ether to send to c via its receive (may be 0)
    // attemptWithdraw: value to pass to withdraw (may be 0)
    function run(uint callDeposit, uint attemptWithdraw) public payable {
        require(address(this).balance >= callDeposit);

        // Observe balance before any interaction
        uint beforeBalance = address(c).balance;

        // Make a deposit attempt by sending Ether to c (invokes receive)
        (bool depositSent, ) = address(c).call{value: callDeposit}("");

        // Observe balance after deposit attempt
        uint midBalance = address(c).balance;

        // Attempt withdraw(amount) and record whether it reverted
        bool withdrawReverted;
        try c.withdraw(attemptWithdraw) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt withdrawAll() and record whether it reverted
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Observe final balance
        uint finalBalance = address(c).balance;

        // General rule asserted:
        // 1) If either withdraw or withdrawAll succeeded (did not revert), then the contract's balance did not increase as a result of those calls
        //    (finalBalance <= midBalance).
        // 2) If both withdraw and withdrawAll reverted, then those calls did not change the contract balance (finalBalance == midBalance).
        // Note: depositSent may be false if receive reverted; midBalance reflects actual result of that.
        assert(
            ( (!withdrawReverted || !withdrawAllReverted) ? (finalBalance <= midBalance) : (finalBalance == midBalance) )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs:
    // depositAmount: amount of wei to send to c via its receive (may be 0)
    // withdrawAmount: value to pass to c.withdraw (may be 0)
    function run(uint depositAmount, uint withdrawAmount) public payable {
        // Ensure this contract can fund the deposit
        require(address(this).balance >= depositAmount);

        // Record balances before any interaction
        uint beforeCTestBal = address(c).balance;
        uint beforeThisBal = address(this).balance;

        // Make a deposit to c by calling its receive (top-level state-changing low-level call)
        (bool depositSent, ) = address(c).call{value: depositAmount}("");

        // Record balances after deposit
        uint afterDepositCTestBal = address(c).balance;
        uint afterDepositThisBal = address(this).balance;

        // Attempt withdraw(withdrawAmount) and record whether it reverted
        bool withdrawReverted;
        try c.withdraw(withdrawAmount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Attempt withdrawAll() and record whether it reverted
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Record final balances
        uint finalCTestBal = address(c).balance;
        uint finalThisBal = address(this).balance;

        // General rule:
        // If either withdraw or withdrawAll succeeded then the test contract's balance should have increased
        // by at least the sum of successful explicit transfer amounts it caused to itself (i.e., withdrawAmount if withdraw succeeded,
        // and address(c).balance prior to withdrawAll call if withdrawAll succeeded cannot be precisely known here —
        // but since withdrawAll calls withdraw(address(this).balance) and onlyOwner is enforced, the effect is: if withdrawAll succeeded,
        // the test contract's final balance must be >= afterDepositThisBal + (withdrawAllSucceeded ? (finalThisBal - afterDepositThisBal) : 0).
        // To make a provable, non-circular assertion over observable values we assert:
        // - If either call succeeded, then finalThisBal >= afterDepositThisBal (i.e., the test contract did not lose Ether because of successful withdraws),
        //   and finalThisBal >= beforeThisBal if any withdraw succeeded (withdraws send Ether to this contract).
        // - If both reverted then finalThisBal == afterDepositThisBal (the withdraw attempts didn't change this contract's balance).

        assert(
            (
                (!withdrawReverted || !withdrawAllReverted)
                ? (finalThisBal >= beforeThisBal)
                : (finalThisBal == afterDepositThisBal)
            )
        );
    }

    // Allow receiving Ether from c during withdraws
    receive() external payable {}
}

