contract InvMutTest {
    C c;
    address deployer;

    constructor(C _c) {
        c = _c;
        deployer = address(_c.owner());
    }

    // single public test function
    function run(address target, uint sendAmount, uint withdrawAmount, bool callAsOwner, bool callWithdrawAll) public payable {
        require(address(this).balance >= sendAmount, "insufficient balance for funding");

        // Fund contract c with sendAmount from this test contract
        c.receive{value: sendAmount}();

        // read observable state before action
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted = false;

        // Decide whether to act as owner or not. If callAsOwner==true, we must call via owner:
        // The checker executes this transaction with msg.sender = InvMutTest, so we cannot change msg.sender.
        // But contract C sets owner at its deployment to msg.sender (the deployer of C). We recorded that address.
        // If callAsOwner is true and this test contract is the owner, we will perform the withdraw; otherwise we expect revert.

        // Use try/catch to detect revert from withdraw or withdrawAll.
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule we assert:
        // - depositsCount only increases when receive() was called (we called it once), so afterDeposits == beforeDeposits.
        // - If the call was performed by the owner (i.e., this test contract is owner), then the withdrawal must NOT revert and contract balance must decrease by at most withdrawAmount (or to zero for withdrawAll).
        // - If this test contract is not the owner, withdraw/withdrawAll must revert and balance must be unchanged.

        bool isOwner = (address(this) == deployer);

        if (isOwner) {
            // as owner, the call should succeed
            // when withdrawAll was called, afterBalance must be <= beforeBalance and equal to 0 if withdrawAll empties contract
            if (callWithdrawAll) {
                assert(reverted == false && afterBalance <= beforeBalance);
            } else {
                // withdraw(amount): afterBalance should be beforeBalance - min(withdrawAmount, beforeBalance)
                // We avoid subtraction in assert; instead check that (beforeBalance >= withdrawAmount => afterBalance == beforeBalance - withdrawAmount)
