                if (beforeBalance >= withdrawAmount) {
                    assert(reverted == false && afterBalance == beforeBalance - withdrawAmount);
                } else {
                    assert(reverted == false && afterBalance == 0);
                }
            }
        } else {
            // not owner: any withdraw attempt must revert and state unchanged
            assert(reverted == true && afterBalance == beforeBalance && afterDeposits == beforeDeposits);
        }
    }

    // receive to accept Ether if owner transfer comes back to this test
    receive() external payable {}
}

