    }

    // We will parametrize: sendAmount (to deposit via receive), withdrawAmount, and a flag tryAsOwner
    // If tryAsOwner == true, InvMutTest calls withdraw; otherwise we simulate a non-owner caller by
    // calling via a low-level call from address(this) but using try/catch cannot change msg.sender.
    // However, the checker runs run(...) exactly once with msg.sender == InvMutTest's deployer for calls to c.
    // The fresh c was deployed with owner = msg.sender at its construction time. According to constraints,
    // the checker deploys a fresh c and then deploys InvMutTest giving that c; therefore owner == address that deployed c,
    // which is NOT this InvMutTest contract. So address(this) (InvMutTest) is generally not owner. We assert that
    // withdraw only succeeds when msg.sender equals c.owner(). To exercise owner-success path we cannot become owner,
    // so we instead assert the general rule that if caller is not owner then withdraw reverts, and if it does not revert
    // then c.balance decreases by the withdrawn amount and depositsCount is non-decreasing relative to before the call.

    // Note: we cannot become owner here, so the successful-withdraw branch will not be reachable in most setups;
    // but the assert must be general: it relates observed revert flag and balances.

    function run(uint sendAmount, uint withdrawAmount, bool callWithdrawAll) public payable {
        require(address(this).balance >= sendAmount);

        // Record balance of contract c before
        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        // Deposit into c by sending Ether to its receive()
        if (sendAmount > 0) {
            // send Ether to c; this will increment depositsCount if not reverted
            (bool ok,) = address(c).call{value: sendAmount}("");
            // ok indicates whether receive succeeded
        }

        uint midBalance = address(c).balance;
        uint midDeposits = c.depositsCount();

        // Attempt to withdraw either a specific amount or withdrawAll. We must capture whether it reverted.
        bool reverted;
        // Because InvMutTest is generally NOT the owner of c, these calls should revert. We capture actual behavior.
        if (callWithdrawAll) {
            try c.withdrawAll() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.withdraw(withdrawAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        // General rule asserted:
        // If the withdraw call did not revert, then the contract's balance must have decreased by exactly the withdrawn amount
        // (for withdrawAll we check that afterBalance == 0), and depositsCount cannot decrease.
        // If the withdraw call reverted, balances and depositsCount must be unchanged from mid-state.
        if (!reverted) {
            // withdrawal succeeded
            if (callWithdrawAll) {
                assert(afterBalance == 0 && afterDeposits >= midDeposits);
            } else {
                // afterBalance should equal midBalance - withdrawAmount
                // avoid underflow by checking midBalance >= withdrawAmount implies exact decrease
                if (midBalance >= withdrawAmount) {
                    assert(afterBalance == midBalance - withdrawAmount && afterDeposits >= midDeposits);
                } else {
                    // if midBalance < withdrawAmount, behavior is that transfer will revert inside withdraw -> unreachable here
                    // so we assert false to indicate such execution should not reach non-reverted branch
                    assert(false);
                }
            }
        } else {
            // reverted: no change to balance or depositsCount compared to mid values
            assert(afterBalance == midBalance && afterDeposits == midDeposits);
        }
    }

    receive() external payable {}
}

