        // (the checker ensures address(this).balance can be arbitrary before run, but we must be safe)
        // So require that the test contract has sufficient balance to send depositAmount.
        require(address(this).balance >= depositAmount, "insufficient balance for depositAmount");

        // Record before-values
        address beforeOwner = c.owner();
        uint256 beforeDeposits = c.depositsCount();
        uint256 beforeBalance = address(c).balance;

        // Make a deposit to c to exercise receive(): must increase depositsCount and c balance.
        // This is a state-changing top-level call that may revert if depositAmount causes issues; we allow it to run.
        c.f{value: depositAmount}();

        // After deposit, record values
        address afterOwner = c.owner();
        uint256 afterDeposits = c.depositsCount();
        uint256 afterBalance = address(c).balance;

        // Now attempt to call withdraw and withdrawAll from this contract (which is NOT the original deployer/owner)
        // Capture whether each call reverted.
        bool withdrewReverted;
        bool withdrawAllReverted;

        try c.withdraw(withdrawAmount) {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Final observed values
        address finalOwner = c.owner();
        uint256 finalDeposits = c.depositsCount();
        uint256 finalBalance = address(c).balance;

