            (finalDeposits >= afterDeposits)
            &&
            // Now enforce non-owner revert behavior: if this contract is not owner, then both calls reverted and balance unchanged
            ( (finalOwner != address(this)) ? (withdrewReverted && withdrawAllReverted && finalBalance == afterBalance) : true )
        );
    }

